import{_ as o,r as n,o as p,c as l,e as a,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Сидинг тем - October CMS - 3.x","titleTemplate":false,"description":"Наполняйте блюпринты и записи базы данных демонстрационным содержимым.","frontmatter":{"subtitle":"Наполняйте блюпринты и записи базы данных демонстрационным содержимым."},"headers":[{"level":2,"title":"Структура директорий","slug":"структура-директории","link":"#структура-директории","children":[]},{"level":2,"title":"Импорт блюпринтов","slug":"импорт-блюпринтов","link":"#импорт-блюпринтов","children":[]},{"level":2,"title":"Импорт языковых файлов","slug":"импорт-языковых-фаилов","link":"#импорт-языковых-фаилов","children":[]},{"level":2,"title":"Импорт данных","slug":"импорт-данных","link":"#импорт-данных","children":[{"level":3,"title":"Пример файла данных","slug":"пример-фаила-данных","link":"#пример-фаила-данных","children":[]}]},{"level":2,"title":"Запуск сидинга темы","slug":"запуск-сидинга-темы","link":"#запуск-сидинга-темы","children":[]}],"relativePath":"3.x/ru/cms/themes/seeding-themes.md","filePath":"3.x/ru/cms/themes/seeding-themes.md"}'),u={name:"3.x/ru/cms/themes/seeding-themes.md"};function i(d,s,k,g,h,m){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[a(t),s[0]||(s[0]=c("h1",null,"Сидинг тем",-1)),a(e),s[1]||(s[1]=r(`<p>Темы поддерживают возможность импорта демонстрационного содержимого из сид-скриптов, включая содержимое базы данных и <a href="./../../cms/tailor/introduction.html">блюпринты Tailor</a>. Для этого используется специальная папка внутри темы под названием <strong>seeds</strong> с определённой структурой директорий.</p><h2 id="структура-директории"><a href="#структура-директории" class="header-anchor">#</a> Структура директорий</h2><p>Ниже представлен пример структуры директории seeds. Директория <strong>blueprints</strong> содержит шаблоны блюпринтов, используемые темой — они автоматически импортируются в директорию <strong>app/blueprints</strong> во вложенную директорию с именем <strong>mywebsite</strong>. Файл <strong>data.yaml</strong> содержит инструкции по импорту содержимого в базу данных.</p><pre class="dir-container"><code><p>├── themes
|   └── mywebsite
|       └── <code>seeds</code>  <em>← Директория сидов темы</em>
|           ├── blueprints
|           |   └── post.yaml  <em>← Файл блюпринта</em>
|           ├── lang
|           |   └── en.json  <em>← Языковой файл</em>
|           ├── data
|           |   └── blog-posts.json  <em>← Файл данных</em>
|           └── data.yaml  <em>← Скрипт сидинга</em></p>
</code></pre><h2 id="импорт-блюпринтов"><a href="#импорт-блюпринтов" class="header-anchor">#</a> Импорт блюпринтов</h2><div class="custom-block aside"><p>Поскольку блюпринты не зависят от конкретной файловой структуры или структуры директорий, их можно свободно перемещать.</p></div><p>При импорте блюпринтов просто поместите файлы блюпринтов в директорию <strong>blueprints</strong>. Конфигурация не требуется — при сидинге все блюпринты просто копируются в директорию <strong>app/blueprints</strong>. Внутри неё создаётся новая директория с тем же именем, что и у темы. Блюпринты помещаются в эту новую директорию.</p><h2 id="импорт-языковых-фаилов"><a href="#импорт-языковых-фаилов" class="header-anchor">#</a> Импорт языковых файлов</h2><p>В качестве дополнительной возможности языковые файлы могут быть импортированы в директорию <strong>app/lang</strong> путём размещения <a href="./../../extend/system/localization.html">JSON-файлов локализации</a> в директории <strong>lang</strong>. Это позволяет переводить метки и другие описания внутри блюпринтов. Если языковой файл уже существует в директории языков приложения, языковые строки будут объединены.</p><h2 id="импорт-данных"><a href="#импорт-данных" class="header-anchor">#</a> Импорт данных</h2><p>Файл <strong>data.yaml</strong> содержит специальный формат, используемый для импорта содержимого в базу данных. В приведённом ниже примере два набора данных импортируются в базу данных для содержимого записей Tailor.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token punctuation">-</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post Data
    <span class="token key atrule">class</span><span class="token punctuation">:</span> Tailor\\Models\\RecordImport
    <span class="token key atrule">file</span><span class="token punctuation">:</span> seeds/data/blog<span class="token punctuation">-</span>posts.json
    <span class="token key atrule">attributes</span><span class="token punctuation">:</span>
        <span class="token key atrule">file_format</span><span class="token punctuation">:</span> json
        <span class="token key atrule">blueprint_uuid</span><span class="token punctuation">:</span> edcd102e<span class="token punctuation">-</span>0525<span class="token punctuation">-</span>4e4d<span class="token punctuation">-</span>b07e<span class="token punctuation">-</span>633ae6c18db6
<span class="token punctuation">-</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Category Data
    <span class="token key atrule">class</span><span class="token punctuation">:</span> Tailor\\Models\\RecordImport
    <span class="token key atrule">file</span><span class="token punctuation">:</span> seeds/data/blog<span class="token punctuation">-</span>categories.json
    <span class="token key atrule">attributes</span><span class="token punctuation">:</span>
        <span class="token key atrule">file_format</span><span class="token punctuation">:</span> json
        <span class="token key atrule">blueprint_uuid</span><span class="token punctuation">:</span> b022a74b<span class="token punctuation">-</span>15e6<span class="token punctuation">-</span>4c6b<span class="token punctuation">-</span>9eb9<span class="token punctuation">-</span>17efc5103543
</code></pre></div><p>YAML-файл должен определять массив, каждый элемент которого поддерживает следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>задаёт имя шага импорта для отображения пользователю.</td></tr><tr><td><strong>class</strong></td><td>ссылается на модель, реализующую интерфейс <code>Backend\\Models\\ImportModel</code>.</td></tr><tr><td><strong>file</strong></td><td>ссылается на JSON-файл данных, содержащий импортируемое содержимое.</td></tr><tr><td><strong>attributes</strong></td><td>список атрибутов, устанавливаемых для модели импорта перед выполнением импорта.</td></tr></tbody></table></div><h3 id="пример-фаила-данных"><a href="#пример-фаила-данных" class="header-anchor">#</a> Пример файла данных</h3><p>Ниже приведён пример JSON-файла, который может использоваться для импорта категорий блога. Каждый элемент JSON-массива создаёт импортированную запись в базе данных с указанными атрибутами. Указание атрибута <strong>id</strong> позволяет связывать записи между несколькими импортами.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">[</span>
    <span class="token punctuation">{</span>
        <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>
        <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Announcements&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;slug&quot;</span><span class="token operator">:</span> <span class="token string">&quot;announcements&quot;</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>
        <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span>
        <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;News&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;slug&quot;</span><span class="token operator">:</span> <span class="token string">&quot;news&quot;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">]</span>
</code></pre></div><h2 id="запуск-сидинга-темы"><a href="#запуск-сидинга-темы" class="header-anchor">#</a> Запуск сидинга темы</h2><p>Для запуска сидинга темы используется artisan-команда <code>theme:seed</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:seed <span class="token operator">&lt;</span>theme name<span class="token operator">&gt;</span>
</code></pre></div><p>Вы также можете использовать опцию <code>--root</code>, чтобы указать команде импортировать блюпринты в корневую директорию вместо вложенной.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:seed <span class="token operator">&lt;</span>theme name<span class="token operator">&gt;</span> <span class="token parameter variable">--root</span>
</code></pre></div><div class="custom-block tip"><p>Сидинг темы также можно выполнить через панель администрирования, перейдя в <strong>Настройки → Фронтенд-тема → Управление → Наполнение содержимым</strong>.</p></div>`,23))])}const _=o(u,[["render",i]]);export{y as __pageData,_ as default};
